(() => {
const {client,escape:esc,safeURL,portraitStyles,defaults}=PortfolioCMS;
const loginView=document.querySelector('#login-view'),studio=document.querySelector('#studio-view'),content=document.querySelector('#studio-content');
const state={projects:[],posts:[],settings:null,panel:['blogs','drafts'].includes(location.hash.slice(1))?location.hash.slice(1):'overview',archived:false,authChecking:false,editor:null,pendingUploads:0};
let toastTimer,authRun=0;
function message(text,error=false){const el=document.querySelector('#studio-message');el.textContent=text;el.className=`studio-message visible${error?' error':''}`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),error?9000:4500)}
function failure(error){console.error('Portfolio studio:',error?.code||error?.name||'request_failed');message(error?.message||'Something went wrong. Please try again.',true)}
function authMessage(text){document.querySelector('#auth-message').textContent=text}
async function request(query){const result=await query;if(result.error)throw result.error;return result.data}
function heading(title,description,action=''){return `<div class="studio-heading"><div><h1>${esc(title)}</h1><p>${esc(description)}</p></div>${action}</div>`}
function val(id){return document.getElementById(id).value.trim()}
function checked(id){return document.getElementById(id).checked}
function field(id,label,value='',type='text',extra=''){return `<label>${esc(label)}<input id="${id}" type="${type}" value="${esc(value)}" ${extra}></label>`}
function textarea(id,label,value='',extra=''){return `<label>${esc(label)}<textarea id="${id}" ${extra}>${esc(value)}</textarea></label>`}
function urlField(id,label,value=''){return field(id,label,value,'text','placeholder="https://…" maxlength="2000"')}
function validateLink(raw){if(!raw)return '';const safe=safeURL(raw);if(!safe)throw Error('Links must use HTTPS or a path on this website.');return raw.startsWith('/')&&!raw.startsWith('//')?raw:safe}
function busy(form,value){form.querySelectorAll('button,input,select,textarea').forEach(el=>el.disabled=value)}
async function loadData(){const [settings,projects,posts]=await Promise.all([PortfolioCMS.getSettings(),request(client.from('portfolio_projects').select('*').order('sort_order').order('created_at')),request(client.from('portfolio_posts').select('*').order('created_at',{ascending:false}))]);state.settings=settings;state.projects=projects;state.posts=posts;await BlogStudio.load();}
async function checkAuth(){if(state.authChecking)return;state.authChecking=true;const run=++authRun;try{const {data:{session}}=await client.auth.getSession();if(!session){studio.hidden=true;loginView.hidden=false;return}const {data:{user},error}=await client.auth.getUser();if(error)throw error;if(!user){studio.hidden=true;loginView.hidden=false;return}const role=await request(client.from('portfolio_admins').select('user_id').eq('user_id',user.id).maybeSingle());if(!role){studio.hidden=true;loginView.hidden=false;authMessage('This account is signed in but has no portfolio administrator access. Sign out below to use the approved account.');let out=document.querySelector('#unauthorized-signout');if(!out){out=document.createElement('button');out.id='unauthorized-signout';out.type='button';out.className='secondary-button';out.textContent='Sign out of this account';out.addEventListener('click',()=>client.auth.signOut());document.querySelector('#login-form').append(out)}return}await loadData();if(run!==authRun)return;document.querySelector('#admin-identity').textContent=user.email;loginView.hidden=true;studio.hidden=false;authMessage('');if(!state.editor){if(BlogStudio.resume()){state.panel='drafts';document.querySelectorAll('[data-panel]').forEach(b=>b.classList.toggle('selected',b.dataset.panel==='drafts'));}else renderPanel(state.panel);}}catch(error){studio.hidden=true;loginView.hidden=false;authMessage(`Studio could not load: ${error.message}. Check the database setup and try again.`);}finally{state.authChecking=false}}
document.querySelector('#login-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget;if(!val('login-password')){authMessage('Enter your password, or choose the email sign-in link.');return}busy(form,true);authMessage('Signing in…');try{const {error}=await client.auth.signInWithPassword({email:val('login-email'),password:val('login-password')});if(error)throw error;document.querySelector('#login-password').value='';await checkAuth()}catch(error){authMessage(error.message)}finally{busy(form,false)}});
document.querySelector('#magic-link').addEventListener('click',async()=>{const email=val('login-email');if(!email||!document.querySelector('#login-email').checkValidity()){authMessage('Enter a valid administrator email.');return}const form=document.querySelector('#login-form');busy(form,true);try{const {error}=await client.auth.signInWithOtp({email,options:{shouldCreateUser:false,emailRedirectTo:`${location.origin}/admin/`}});if(error)throw error;authMessage('Check your email for the sign-in link. Open it in this browser.')}catch(error){authMessage(error.message)}finally{busy(form,false)}});
document.querySelector('#sign-out').addEventListener('click',async()=>{const {error}=await client.auth.signOut();if(error)return failure(error);BlogStudio.close();state.editor=null;studio.hidden=true;loginView.hidden=false;authMessage('You’ve been signed out.')});
client.auth.onAuthStateChange(event=>{if(event==='SIGNED_OUT'){authRun++;BlogStudio.close();state.editor=null;studio.hidden=true;loginView.hidden=false}else if(event==='PASSWORD_RECOVERY'||(event==='SIGNED_IN'&&studio.hidden))setTimeout(checkAuth,0)});
document.querySelectorAll('[data-panel]').forEach(button=>button.addEventListener('click',async()=>{if(state.editor?.kind==='post'){if(!(await BlogStudio.leave()))return message('Your draft is kept on this device. Retry Save draft before leaving.',true);}if(state.editor?.dirty&&!window.confirm('Leave this editor and discard unsaved changes?'))return;state.editor=null;state.archived=false;renderPanel(button.dataset.panel)}));
function renderPanel(panel){state.panel=panel;if(['blogs','drafts'].includes(panel))history.replaceState(null,'','#'+panel);document.querySelectorAll('[data-panel]').forEach(b=>b.classList.toggle('selected',b.dataset.panel===panel));({overview:renderOverview,projects:renderProjects,portrait:renderPortrait,blogs:()=>renderPosts('published'),drafts:()=>renderPosts('drafts'),settings:renderSettings})[panel]();}
function renderOverview(){const active=state.projects.filter(p=>!p.archived);content.innerHTML=heading('Make it yours.','A good place to keep your portfolio moving forward.')+`<div class="stats"><div class="stat"><strong>${active.length}</strong><span>Projects in your collection</span></div><div class="stat"><strong>${active.filter(p=>p.published).length}</strong><span>Published projects</span></div><div class="stat"><strong>${state.posts.filter(p=>!p.archived).length}</strong><span>Blog posts · ${state.settings.blogs_enabled?'enabled':'hidden'}</span></div></div><div class="studio-banner"><h2>Small updates. A living portfolio.</h2><p>Edit your projects, upload a fresh image, or give a new idea a home. Changes go live when you save; drafts stay private.</p><div class="quick-links"><button class="secondary-button" data-quick="projects">Edit projects ↗</button><button class="secondary-button" data-quick="portrait">Style your portrait ↗</button><button class="secondary-button" data-quick="blogs">Write a post ↗</button></div></div>`;content.querySelectorAll('[data-quick]').forEach(b=>b.addEventListener('click',()=>renderPanel(b.dataset.quick)));
const account=document.createElement('section');account.className='studio-banner';account.innerHTML='<h2>Your sign-in password</h2><p>Set or update the password for your own administrator account. You can also keep using email sign-in links.</p><form id="account-password-form"><div class="field-pair"><label>New password<input id="new-account-password" type="password" autocomplete="new-password" required minlength="8"></label><label>Confirm password<input id="confirm-account-password" type="password" autocomplete="new-password" required minlength="8"></label></div><button type="submit" class="admin-button">Save my password</button></form>';content.append(account);
account.querySelector('form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget;const first=document.querySelector('#new-account-password'),second=document.querySelector('#confirm-account-password');if(first.value!==second.value)return message('The passwords do not match.',true);busy(form,true);try{const {error}=await client.auth.updateUser({password:first.value});if(error)throw error;form.reset();message('Your sign-in password has been updated.')}catch(error){failure(error)}finally{busy(form,false)}});
}
function itemRows(items,kind){if(!items.length)return `<div class="empty-state">${state.archived?'No archived items.':'Nothing here yet. Add your first '+(kind==='project'?'project':'post')+'.'}</div>`;return `<div class="item-list">${items.map(p=>`<article class="item-row">${safeURL(p.cover_url)?`<img src="${esc(safeURL(p.cover_url))}" alt="${esc(p.title)}">`:'<div class="image-placeholder" aria-hidden="true">✳</div>'}<div class="row-main"><h3>${esc(p.title)}</h3><p><span class="badge ${p.archived?'archived':p.published?'':'draft'}">${p.archived?'Archived':p.published?'Published':'Draft'}</span>${esc(kind==='project'?p.description:p.excerpt)}</p></div><div class="row-actions"><button data-edit="${esc(p.id)}">Edit</button><button data-archive="${esc(p.id)}">${p.archived?'Restore':'Archive'}</button></div></article>`).join('')}</div>`}
function bindList(items,kind){content.querySelector('#new-item').addEventListener('click',()=>kind==='project'?editProject():editPost());content.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{state.archived=b.dataset.filter==='archived';kind==='project'?renderProjects():renderPosts()}));content.querySelectorAll('[data-edit]').forEach(b=>b.addEventListener('click',()=>{const p=items.find(p=>p.id===b.dataset.edit);kind==='project'?editProject(p):editPost(p)}));content.querySelectorAll('[data-archive]').forEach(b=>b.addEventListener('click',()=>archiveItem(items.find(p=>p.id===b.dataset.archive),kind)));}
function listTabs(){return `<div class="admin-tabs"><button data-filter="active" class="${!state.archived?'active':''}">Current</button><button data-filter="archived" class="${state.archived?'active':''}">Archived</button></div>`}
function renderProjects(){content.innerHTML=heading('Your projects.','Tell the story. Show the details. Keep the best work up front.','<button id="new-item" class="admin-button">Add project +</button>')+listTabs()+itemRows(state.projects.filter(p=>p.archived===state.archived),'project');bindList(state.projects,'project')}
function renderPosts(view='published'){BlogStudio.render(view)}
function askArchive(){return new Promise(resolve=>{const modal=document.querySelector('#confirm-dialog');let done=false;const finish=value=>{if(done)return;done=true;modal.close();resolve(value)};document.querySelector('#confirm-cancel').onclick=()=>finish(false);document.querySelector('#confirm-archive').onclick=()=>finish(true);modal.oncancel=()=>finish(false);modal.showModal()})}
async function archiveItem(item,kind){if(!item.archived&&!(await askArchive()))return;try{await request(client.from(kind==='project'?'portfolio_projects':'portfolio_posts').update({archived:!item.archived}).eq('id',item.id).eq('updated_at',item.updated_at).select().single());await loadData();kind==='project'?renderProjects():renderPosts();message(item.archived?'Restored. Publish it when you’re ready.':'Archived. You can restore it anytime.')}catch(error){failure(error)}}
function editorEvents(form){form.addEventListener('input',()=>{state.editor.dirty=true});form.addEventListener('change',()=>{state.editor.dirty=true});document.querySelector('#cancel-edit').addEventListener('click',()=>{if(state.editor.dirty&&!window.confirm('Discard unsaved changes?'))return;state.editor=null;renderPanel(state.panel)})}
function projectForm(p){return `<form id="project-form">${ProjectCoverEditor.panel(p)}<div class="editor-layout"><section class="editor-card"><h2>Project story</h2>${field('project-title','Project title',p.title,'text','required maxlength="160"')}${textarea('project-description','Short description',p.description,'maxlength="500"')}${textarea('project-intro','Introduction',p.intro)}${textarea('project-story','The idea / project text',p.story)}${textarea('project-approach','How it fits together',p.approach)}${textarea('project-status','Status and context',p.status_note)}${field('project-tags','Tags, separated by commas',(p.tags||[]).join(', '),'text','maxlength="500"')}<div class="field-pair">${urlField('project-repo','Repository link',p.repository_url)}${urlField('project-demo','Live demo link',p.demo_url)}</div></section><section class="editor-card"><h2>Gallery & publishing</h2>${field('project-order','Display order',p.sort_order||0,'number','min="0" max="9999"')}<label class="check-label"><input type="checkbox" id="project-published" ${p.published?'checked':''}>Publish on the portfolio</label><h3>Additional images</h3><label>Add project pictures<input id="gallery-upload" type="file" multiple accept="image/jpeg,image/png,image/webp,image/avif"></label><div id="gallery-preview" class="gallery-preview"></div><p class="hint">Up to 12 images. Removing an image here removes it from this project after you save.</p></section></div><div class="form-actions"><button class="admin-button" type="submit">Save project ✓</button><button class="secondary-button" type="button" id="cancel-edit">Cancel</button><span class="saving-note">Your cover design and project details are saved together.</span></div></form>`}
function editProject(existing){const p=existing||{id:crypto.randomUUID(),title:'',description:'',intro:'',story:'',approach:'',status_note:'',tags:[],cover_url:'',gallery:[],cover_color:'lilac',sort_order:state.projects.length,published:false,archived:false};state.editor={kind:'project',id:p.id,dirty:false,gallery:structuredClone(p.gallery||[])};content.innerHTML=heading(existing?'Make the details count.':'A new project starts here.','Write in plain text. Your words are displayed safely, just as you enter them.')+projectForm(p);const form=document.querySelector('#project-form');editorEvents(form);ProjectCoverEditor.mount(form,p,()=>{state.editor.dirty=true});renderGallery();document.querySelector('#project-cover').addEventListener('input',updateCoverPreview);document.querySelector('#cover-upload').addEventListener('change',event=>handleCoverUpload(event,'project-cover'));document.querySelector('#gallery-upload').addEventListener('change',async event=>{const input=event.target,files=[...input.files];if(state.editor.gallery.length+files.length>12)return message('Use up to 12 additional images per project.',true);input.disabled=true;state.pendingUploads++;try{for(const file of files){const url=await uploadImage(file,'projects');state.editor.gallery.push({url,alt:file.name.replace(/\.[^.]+$/,'')})}state.editor.dirty=true;renderGallery();message('Images uploaded. Save the project to publish these changes.')}catch(error){failure(error)}finally{input.value='';input.disabled=false;state.pendingUploads--}});form.addEventListener('submit',async event=>{event.preventDefault();if(state.pendingUploads)return message('Please wait for the image uploads to finish.',true);busy(form,true);try{const item={id:p.id,title:val('project-title'),description:val('project-description'),intro:val('project-intro'),story:val('project-story'),approach:val('project-approach'),status_note:val('project-status'),tags:val('project-tags').split(',').map(t=>t.trim()).filter(Boolean).slice(0,20),cover_url:validateLink(val('project-cover')),cover_layout:ProjectCoverEditor.read(),gallery:state.editor.gallery,cover_color:val('project-color'),sort_order:Math.max(0,Math.min(9999,Number(val('project-order'))||0)),repository_url:validateLink(val('project-repo')),demo_url:validateLink(val('project-demo')),published:checked('project-published'),archived:p.archived||false};if(existing)await request(client.from('portfolio_projects').update(item).eq('id',p.id).eq('updated_at',p.updated_at).select().single());else await request(client.from('portfolio_projects').insert(item).select().single());state.editor=null;await loadData();renderProjects();message('Project saved.')}catch(error){failure(error);busy(form,false)}});window.scrollTo({top:0,behavior:'instant'})}
function updateCoverPreview(){if(document.querySelector('#project-form'))ProjectCoverEditor.refresh();const preview=document.querySelector('#cover-preview');const url=safeURL(document.querySelector('#project-cover')?.value||document.querySelector('#post-cover')?.value);preview.hidden=!url;if(url)preview.src=url;else preview.removeAttribute('src')}
function renderGallery(){const target=document.querySelector('#gallery-preview');if(!target)return;target.innerHTML=state.editor.gallery.map((image,index)=>`<div class="gallery-tile"><img src="${esc(safeURL(image.url))}" alt="${esc(image.alt||'Project image')}"><button type="button" data-remove="${index}" aria-label="Remove image ${index+1}">×</button></div>`).join('');target.querySelectorAll('[data-remove]').forEach(b=>b.addEventListener('click',()=>{state.editor.gallery.splice(Number(b.dataset.remove),1);state.editor.dirty=true;renderGallery()}))}
async function uploadImage(file,folder){if(!file||!['image/jpeg','image/png','image/webp','image/avif'].includes(file.type))throw Error('Choose a JPG, PNG, WebP, or AVIF image.');if(file.size>10485760)throw Error('Choose an image smaller than 10 MB.');const bitmap=await createImageBitmap(file);const scale=Math.min(1,1920/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/webp',.88));if(!blob)throw Error('This image could not be processed. Try another file.');const path=`${folder}/${crypto.randomUUID()}.webp`;const {error}=await client.storage.from('portfolio-media').upload(path,blob,{contentType:'image/webp',cacheControl:'31536000',upsert:false});if(error)throw error;return client.storage.from('portfolio-media').getPublicUrl(path).data.publicUrl}
async function handleCoverUpload(event,targetId){const input=event.target,file=input.files?.[0];if(!file)return;input.disabled=true;state.pendingUploads++;try{const url=await uploadImage(file,state.editor.kind==='post'?'blogs':'projects');document.getElementById(targetId).value=url;state.editor.dirty=true;updateCoverPreview();message('Cover uploaded. Save to apply it.')}catch(error){failure(error)}finally{input.value='';input.disabled=false;state.pendingUploads--}}
function range(id,label,value,min,max,unit='%'){return `<label><span class="range-heading"><span>${label}</span><output for="${id}">${value}${unit}</output></span><input id="${id}" type="range" min="${min}" max="${max}" value="${value}"></label>`}
function renderPortrait(){const p={...defaults,...state.settings.portrait};state.editor={kind:'portrait',dirty:false};content.innerHTML=heading('Your picture. Your frame.','Adjust the crop, shape, and finish. The preview updates as you move the controls.')+`<form id="portrait-form"><div class="editor-layout"><section class="editor-card"><h2>Portrait image</h2>${urlField('portrait-url','Image URL',p.url)}<label>Upload a new picture<input id="portrait-upload" type="file" accept="image/jpeg,image/png,image/webp,image/avif"></label><p class="hint">One portrait, used in the About section. The frame contains only “HELLO, I’M SATHWIK.”</p><label>Frame shape<select id="portrait-shape">${Object.entries({circle:'Circle',arch:'Arch',rounded:'Rounded rectangle',square:'Square'}).map(([key,name])=>`<option value="${key}" ${p.shape===key?'selected':''}>${name}</option>`).join('')}</select></label><div class="portrait-controls">${range('portrait-size','Frame width',p.size,60,100)}${range('portrait-height','Frame height',p.height,240,520,'px')}${range('portrait-zoom','Image zoom',p.zoom,100,200)}${range('portrait-x','Horizontal position',p.x,0,100)}${range('portrait-y','Vertical position',p.y,0,100)}${range('portrait-grayscale','Black & white',p.grayscale,0,100)}${range('portrait-brightness','Brightness',p.brightness,50,150)}${range('portrait-saturation','Color intensity',p.saturation,0,200)}</div><p class="hint">A circular frame keeps equal width and height. Height applies to other shapes.</p><button type="button" id="portrait-reset" class="secondary-button">Reset frame & filters</button></section><aside class="portrait-preview-wrap"><div class="portrait-slot" id="portrait-preview"><span class="portrait-corner">HELLO, I’M SATHWIK.</span></div></aside></div><div class="form-actions"><button class="admin-button" type="submit">Save portrait ✓</button><button class="secondary-button" type="button" id="cancel-edit">Cancel</button><span class="saving-note">Preview changes stay local until you save.</span></div></form>`;const form=document.querySelector('#portrait-form');editorEvents(form);const read=()=>({url:val('portrait-url'),shape:val('portrait-shape'),...Object.fromEntries(['size','height','zoom','x','y','grayscale','brightness','saturation'].map(key=>[key,Number(document.getElementById('portrait-'+key).value)]))});const preview=()=>{const values=read(),slot=document.querySelector('#portrait-preview'),safe=safeURL(values.url);let img=slot.querySelector('img');if(safe){if(!img){img=document.createElement('img');img.alt='Portrait preview';slot.prepend(img)}if(img.src!==safe)img.src=safe}else img?.remove();portraitStyles(slot,values);form.querySelectorAll('input[type=range]').forEach(input=>input.closest('label').querySelector('output').textContent=input.value+(input.id==='portrait-height'?'px':'%'))};form.addEventListener('input',preview);form.addEventListener('change',preview);document.querySelector('#portrait-upload').addEventListener('change',async event=>{const input=event.target,file=input.files?.[0];if(!file)return;input.disabled=true;state.pendingUploads++;try{document.querySelector('#portrait-url').value=await uploadImage(file,'portrait');state.editor.dirty=true;preview();message('Portrait uploaded. Save when the frame feels right.')}catch(error){failure(error)}finally{input.disabled=false;input.value='';state.pendingUploads--}});document.querySelector('#portrait-reset').addEventListener('click',()=>{for(const [key,value] of Object.entries(defaults)){if(key==='url')continue;document.getElementById('portrait-'+key).value=value}state.editor.dirty=true;preview()});form.addEventListener('submit',async event=>{event.preventDefault();if(state.pendingUploads)return message('Please wait for the upload to finish.',true);busy(form,true);try{const portrait=read();portrait.url=validateLink(portrait.url);await request(client.from('portfolio_settings').update({portrait}).eq('id','main').eq('updated_at',state.settings.updated_at).select().single());await loadData();renderPortrait();state.editor.dirty=false;message('Portrait and frame saved.')}catch(error){failure(error);busy(form,false)}});preview()}
function editPost(existing){BlogStudio.open(existing)}
function renderSettings(){content.innerHTML=heading('A few little switches.','Choose what the world can see.')+`<form id="settings-form" class="editor-card"><div class="settings-toggle"><div><h3>Enable the blog</h3><p>Show Blogs in the website navigation and allow published posts to be read at /blogs. Turning this off hides the page and keeps the posts saved.</p></div><label class="check-label"><input id="blogs-enabled" type="checkbox" ${state.settings.blogs_enabled?'checked':''} aria-label="Enable the blog"></label></div><div class="form-actions"><button class="admin-button" type="submit">Save settings ✓</button><a class="text-link" href="/blogs/" target="_blank" rel="noopener">Open blog ↗</a></div><p class="hint">The studio opens only at /admin. Its location is not advertised on the public site. All writes also require an approved Supabase Auth account.</p></form>`;document.querySelector('#settings-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget;busy(form,true);try{await request(client.from('portfolio_settings').update({blogs_enabled:checked('blogs-enabled')}).eq('id','main').eq('updated_at',state.settings.updated_at).select().single());await loadData();renderSettings();message('Site settings saved.')}catch(error){failure(error);busy(form,false)}})}
window.addEventListener('beforeunload',event=>{if(state.editor?.kind==='post'){if(BlogStudio.backup()){event.preventDefault();event.returnValue=''}return}if(state.editor?.dirty){event.preventDefault();event.returnValue=''}});
BlogStudio.configure({root:content,heading,message,failure,posts:()=>state.posts,enabled:()=>state.settings.blogs_enabled,upload:uploadImage,pending:()=>state.pendingUploads,uploading:delta=>state.pendingUploads+=delta,setEditor:editor=>state.editor={...editor,kind:'post',get dirty(){return editor.dirty}},clearEditor:()=>state.editor=null,reload:loadData,navigate:view=>{state.editor=null;state.panel=view==='drafts'?'drafts':'blogs';history.replaceState(null,'','#'+state.panel);document.querySelectorAll('[data-panel]').forEach(b=>b.classList.toggle('selected',b.dataset.panel===state.panel));BlogStudio.render(view)},archive:item=>archiveItem(item,'post')});
checkAuth();
})();
